Azure App Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(azure_app_service, "Azure App Service") {
    Component(Azure Modular Monolith Platform, "Azure Modular Monolith Platform", "Azure App Service (Premium V3 Tier)", "Hosts the core claims management workflows and business logic.")
    Component(Anti-Corruption Layer (ACL), "Anti-Corruption Layer (ACL)", "Azure App Service", "Translates and adapts messages between the cloud platform and the legacy mainframe.")
}

Rel(Azure Modular Monolith Platform, Anti-Corruption Layer (ACL), "Delegates hybrid communication")

@enduml

Azure Redis Cache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(azure_redis_cache, "Azure Redis Cache") {
    Component(Cache_Manager, "Cache Manager", "Redis Protocol", "Manages transient read models and cache-aside operations to ensure sub-2-second UI response times.")
    Component(Cache_Invalidation_Service, "Cache Invalidation Service", "AMQP Listener", "Handles cache eviction and invalidation messages received from the Azure Service Bus.")
}

Rel(Cache_Manager, Cache_Invalidation_Service, "Triggers invalidation routines on domain events")

@enduml

Azure Application Insights.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure Application Insights container

Container_Boundary("Azure Application Insights", "Azure Application Insights") {
    Component("Telemetry_Collector", "Telemetry Collector", "Application Insights SDK", "Collects telemetry, logs, and trace data from the Azure App Service.")
    Component("Distributed_Tracer", "Distributed Tracer", "OpenTelemetry / Application Insights", "Ensures distributed tracing and observability across the hybrid cloud-mainframe boundary.")
}

Rel(Telemetry_Collector, Distributed_Tracer, "Forwards collected logs and metrics for analysis", "HTTPS")

@enduml
